sys_script_include.script:
var RIDEClientAPI = Class.create();
RIDEClientAPI.prototype = Object.extendsObject(global.AbstractAjaxProcessor,
{
	GetApps: function()
	{
		var MakeJson = x_snc_devtools.MakeJson;

		var aApps = GetApps();
		return MakeJson(aApps);
	},	

	GetAppData: function()
	{
		var GetParam = x_snc_devtools.GetParam;
		var IsValidSysId = x_snc_devtools.IsValidSysId;
		var MakeJson = x_snc_devtools.MakeJson;

		var strAppSysId = GetParam('app_sys_id',IsValidSysId);
		var strMode = GetParam('mode');
		var appdata = GetAppData(strAppSysId,strMode);
		return MakeJson(appdata);
	},

	GetAppFileClasses: function()
	{
		var MakeJson = x_snc_devtools.MakeJson;
		var app_file_classes = GetAppFileClasses();
		return MakeJson(app_file_classes);
	},

	CreateAppFile: function()
	{
		var GetParam = x_snc_devtools.GetParam;
		var IsValidSysId = x_snc_devtools.IsValidSysId;
		var Clone = x_snc_devtools.Clone;
		var MakeJson = x_snc_devtools.MakeJson;

		var strAppSysId = GetParam('app_sys_id',IsValidSysId);
		var strClassName = GetParam('class_name');		
		var grRecord = CreateAppFile(strAppSysId,strClassName);
		return MakeJson(grRecord);
	},

	AppCreate: function()
	{
		var GetParam = x_snc_devtools.GetParam;
		var IsValidScope = x_snc_devtools.IsValidScope;
		var AppCreate = x_snc_devtools.AppCreate;

		var strAppName = GetParam('app_name');		
		var strAppType = GetParam('app_type');
		var strAppScope = GetParam('app_scope',IsValidScope);	
		var strAppSysId = AppCreate(strAppName,strAppType,strAppScope);
		return strAppSysId;
	},	

	SetUserState: function()
	{
		var GetParam = x_snc_devtools.GetParam;
		var IsValidSysId = x_snc_devtools.IsValidSysId;
		var GetStringValue = x_snc_devtools.GetStringValue;
		var ParseJson = x_snc_devtools.ParseJson;

		var strAppSysId = GetParam('app_sys_id',IsValidSysId);		
		var strState = GetParam('state');
		var strUserSysId = GetStringValue(gs.getUserID());
		var state = ParseJson(strState); 

		return SetUserState(strUserSysId, strAppSysId, state);
	},

	GetUserState: function()
	{
		var GetParam = x_snc_devtools.GetParam;
		var IsValidSysId = x_snc_devtools.IsValidSysId;		
		var GetStringValue = x_snc_devtools.GetStringValue;
		var MakeJson = x_snc_devtools.MakeJson;

		var strAppSysId = GetParam('app_sys_id',IsValidSysId);			
		var strUserSysId = GetStringValue(gs.getUserID());

		return MakeJson(GetUserState(strUserSysId, strAppSysId));
	},	

    type: 'RIDEClientAPI'
});
